describe('Physical .13: 40 complete browser samples', () => {
  for (let round = 0; round < 20; round++)
    for (const [offset, mode] of (['RUN', 'SUBMIT'] as const).entries()) {
      const id = `${mode}-${round + 1}`;
      it(`${id} Activar ${mode}8 → resultado durable renderizado`, () =>
        prepare('NORMAL').then((c) => {
          const a = c.actors[(round * 2 + offset) % 8]!,
            f = a.fixtures[mode];
          const measure: Measurement = {
            id,
            mode,
            actorId: a.id,
            started: null,
            durationMs: null,
            clock: null,
            proof: null,
            recorded: false,
            dispose: null,
          };
          measurement = measure;
          let expectedAttempt: string | null = null;
          visit(c, a.id, path(a, mode));
          edit(f.successCode);
          cy.intercept('POST', `**${endpoint(a, mode)}`, (req) =>
            req.continue((res) => {
              expectedAttempt = res.body?.data?.attemptId ?? null;
            }),
          ).as('measured');
          if (mode === 'SUBMIT') cy.get(sel('submit-code')).click();
          cy.window({ log: false }).then((win) => {
            measure.clock = () => win.performance.now();
            const observer = new win.MutationObserver(() => {
              const diagnosis = win.document.querySelector(
                sel(mode === 'RUN' ? 'run-diagnosis' : 'attempt-diagnosis'),
              );
              const correct =
                diagnosis?.textContent?.includes('SUCCESS') &&
                (mode === 'RUN' ||
                  (!!expectedAttempt &&
                    win.document
                      .querySelector(sel('attempt-id'))
                      ?.textContent?.includes(expectedAttempt)));
              if (
                correct &&
                measure.started !== null &&
                measure.durationMs === null
              )
                win.requestAnimationFrame(() => {
                  if (measure.durationMs === null) {
                    measure.durationMs =
                      win.performance.now() - measure.started!;
                    observer.disconnect();
                  }
                });
            });
            observer.observe(win.document.body, {
              childList: true,
              subtree: true,
              characterData: true,
            });
            measure.dispose = () => observer.disconnect();
            win.document
              .querySelector(
                sel(mode === 'RUN' ? 'run-code' : 'confirm-submit'),
              )!
              .addEventListener(
                'click',
                () => {
                  measure.started = win.performance.now();
                },
                { once: true, capture: true },
              );
          });
          cy.get(sel(mode === 'RUN' ? 'run-code' : 'confirm-submit'))
            .should('be.enabled')
            .click();
          cy.wait('@measured', { log: false, responseTimeout: 45000 })
            .then(({ request, response }) =>
              task<Proof>('verify', {
                scope: c.scope,
                actorId: a.id,
                mode,
                key: String(request.headers['idempotency-key']),
                status: response!.statusCode,
                payload: response!.body,
                code: f.successCode,
                diagnosis: 'SUCCESS',
              }),
            )
            .then((proof) => {
              measure.proof = proof;
            });
          result(mode);
          cy.wrap(null, { log: false }).should(() =>
            expect(measure.durationMs).to.be.a('number'),
          );
          cy.then(() => {
            const p = measure.proof!;
            return task('row', {
              id,
              profile: 'normal',
              mode,
              actorId: a.id,
              requestId: p.requestId,
              executionId: p.executionId,
              attemptId: p.attemptId,
              durationMs: measure.durationMs,
              pass: true,
              failureCodes: [],
              observationSha256: p.observationSha256,
            }).then(() => {
              measure.recorded = true;
            });
          });
        }));
    }
});
